INSERT INTO `document_chunks` (`id`, `uid`, `ordinal`, `title`, `content`, `content_hash`, `char_count`, `tokens`, `tags`, `source_name`, `chapter`, `embedding`, `embedding_provider`, `embedding_model`, `embedding_dim`, `embedding_norm`, `created_at`, `updated_at`, `course_id`, `document_id`, `knowledge_point_id`) VALUES (52,'CH-DOC-ML-001-001',1,'1.1 监督学习与假设空间','监督学习从带标签的数据中学习输入到输出的映射。设输入空间为 X、输出空间为 Y，学习器的任务是在假设空间 H 中寻找一个函数 f，使它对未见样本也有良好的预测能力。分类与回归是最常见的两类监督学习任务。\n\n学习机器学习之前需要具备三块基础：线性代数帮助我们理解特征空间、矩阵分解与模型参数；概率统计提供条件概率、贝叶斯公式和分布建模的语言；微积分提供梯度与链式法则，是反向传播的数学前提。Python 和 NumPy 则负责把公式落实成可运行实验。\n\n假设空间过小会导致欠拟合，过大则容易记住训练集噪声。模型选择的目标不是让训练误差最小，而是在偏差与方差之间取得平衡。数据划分、特征工程与正则化共同决定最终泛化表现。','7665346e2b2c77724141cd62e8eeaa89b2a970ab68eb9112d538028581dfbb53',308,'{\"章\": 1, \"第\": 1, \"numpy\": 1, \"python\": 1, \"三块\": 1, \"不是\": 1, \"与优\": 1, \"与假\": 1, \"与回\": 1, \"与方\": 1, \"与模\": 1, \"与正\": 1, \"与链\": 1, \"两类\": 1, \"个函\": 1, \"中学\": 1, \"中寻\": 1, \"之前\": 1, \"之间\": 1, \"也有\": 1, \"习与\": 1, \"习之\": 1, \"习从\": 1, \"习任\": 1, \"习器\": 1, \"习机\": 1, \"习范\": 1, \"习输\": 1, \"从带\": 1, \"代数\": 1, \"们理\": 1, \"件概\": 1, \"任务\": 2, \"优化\": 1, \"会导\": 1, \"传播\": 1, \"住训\": 1, \"使它\": 1, \"供条\": 1, \"供梯\": 1, \"假设\": 3, \"偏差\": 1, \"入到\": 1, \"入空\": 1, \"公式\": 2, \"共同\": 1, \"具备\": 1, \"决定\": 1, \"出的\": 1, \"出空\": 1, \"函数\": 1, \"分布\": 1, \"分提\": 1, \"分类\": 1, \"分解\": 1, \"划分\": 1, \"则化\": 1, \"则容\": 1, \"则负\": 1, \"到输\": 1, \"前提\": 1, \"前需\": 1, \"务是\": 1, \"助我\": 1, \"化共\": 1, \"化表\": 1, \"参数\": 1, \"反向\": 1, \"取得\": 1, \"可运\": 1, \"叶斯\": 1, \"同决\": 1, \"向传\": 1, \"和分\": 1, \"器学\": 1, \"器的\": 1, \"噪声\": 1, \"回归\": 1, \"在假\": 1, \"在偏\": 1, \"块基\": 1, \"型参\": 1, \"型选\": 1, \"基础\": 1, \"备三\": 1, \"大则\": 1, \"好的\": 1, \"学习\": 8, \"学前\": 1, \"它对\": 1, \"定最\": 1, \"实成\": 1, \"实验\": 1, \"容易\": 1, \"对未\": 1, \"寻找\": 1, \"导致\": 1, \"小会\": 1, \"工程\": 1, \"差与\": 1, \"差之\": 1, \"差最\": 1, \"布建\": 1, \"带标\": 1, \"帮助\": 1, \"常见\": 1, \"平衡\": 1, \"度与\": 1, \"建模\": 1, \"式与\": 1, \"式和\": 1, \"式法\": 1, \"式落\": 1,