56:10.581903',15,16,89),(91,'CH-DOC-DB-001-002',2,'1.2 SQL 查询与聚合','SQL 查询通常由 FROM、WHERE、GROUP BY、HAVING、SELECT、ORDER BY 和 LIMIT 组成。聚合函数对分组数据计算统计值，窗口函数可以在不折叠行的前提下完成排名、累计与移动平均。\n\n连接用于组合多张表，内连接只保留匹配行，左连接保留左表全部行。子查询可以出现在 WHERE、FROM 或 SELECT 中；相关子查询会引用外层查询的字段。\n\n编写查询时要明确执行顺序和 NULL 语义。COUNT(*) 与 COUNT(column) 结果可能不同，NOT IN 遇到 NULL 可能产生意外结果。复杂查询应通过执行计划和测试数据验证。','354e61ca6783b8d136dfb1342dc5ee1b52eeff98aa3a3641eea34b2d72e96c9e',286,'{\"by\": 2, \"in\": 1, \"not\": 1, \"sql\": 2, \"章\": 1, \"第\": 1, \"null\": 2, \"count\": 2, \"group\": 1, \"limit\": 1, \"order\": 1, \"where\": 2, \"column\": 1, \"having\": 1, \"select\": 2, \"下完\": 1, \"不同\": 1, \"不折\": 1, \"与查\": 1, \"与移\": 1, \"与聚\": 1, \"于组\": 1, \"产生\": 1, \"以出\": 1, \"以在\": 1, \"会引\": 1, \"保留\": 2, \"全部\": 1, \"关子\": 1, \"关系\": 1, \"内连\": 1, \"写查\": 1, \"出现\": 1, \"函数\": 2, \"分组\": 1, \"划和\": 1, \"前提\": 1, \"动平\": 1, \"匹配\": 1, \"叠行\": 1, \"口函\": 1, \"只保\": 1, \"可能\": 2, \"合函\": 1, \"合多\": 1, \"和测\": 1, \"在不\": 1, \"型与\": 1, \"复杂\": 1, \"外层\": 1, \"外结\": 1, \"多张\": 1, \"子查\": 2, \"字段\": 1, \"完成\": 1, \"对分\": 1, \"层查\": 1, \"左表\": 1, \"左连\": 1, \"常由\": 1, \"平均\": 1, \"序和\": 1, \"应通\": 1, \"引用\": 1, \"张表\": 1, \"意外\": 1, \"成排\": 1, \"执行\": 2, \"折叠\": 1, \"据计\": 1, \"据验\": 1, \"排名\": 1, \"接保\": 1, \"接只\": 1, \"接用\": 1, \"提下\": 1, \"数可\": 1, \"数对\": 1, \"数据\": 2, \"时要\": 1, \"明确\": 1, \"杂查\": 1, \"果可\": 1, \"查询\": 8, \"模型\": 1, \"测试\": 1, \"现在\": 1, \"生意\": 1, \"用于\": 1, \"用外\": 1, \"留匹\": 1, \"留左\": 1, \"的前\": 1, \"的字\": 1, \"相关\": 1, \"确执\": 1, \"移动\": 1, \"窗口\": 1, \"算统\": 1, \"系模\": 1, \"累计\": 1, \"组合\": 1, \"组成\": 1, \"组数\": 1, \"结果\": 2, \"统计\": 1, \"编写\": 1, \"聚合\": 2, \"能不\": 1, \"能产\": 1, \"行的\": 1, \"行计\": 1, \"行顺\": 1, \"表全\": 1, \"要明\": 1, \"计与\": 1, \"计值\": 1, \"计划\": 1, \"计算\": 1, \"试数\": 1, \"询与\": 1, \"询会\": 1, \"询可\": 1, \"询应\": 1, \"询时\": 1, \"询的\": 1, \"询通\": 1, \"语义\": 1, \"过执\": 1, \"连接\": 3, \"通常\": 1, \"遇到\": 1, \"部行\": 1, \"配行\": 1, \"顺序\": 1, \"验证\": 1}','[\"DB\", \"数据库系统\", \"SQL 查询与聚合\", \"查询\"