459125, -0.13117857, 0.0459125, -0.0819866]','local','blake2b-char-ngram-v1',384,1,'2026-11-07 10:56:10.616362','2026-11-07 10:56:10.616406',16,17,98),(100,'CH-DOC-NET-001-005',5,'5.2 DNS 与 CDN','DNS 把域名解析为 IP 地址，形成分层分布式系统。递归解析器从根域、顶级域到权威服务器逐级查询，并缓存结果。TTL 决定缓存时间，影响故障切换速度。\n\nDNS 轮询可以实现简单负载分发，但健康检查和会话保持能力有限。CDN 通过边缘节点缓存静态资源，使用就近访问降低延迟，并通过缓存键与回源策略控制一致性。\n\nDNS 故障常表现为“网站打不开但 IP 可访问”。排查时要检查解析结果、TTL、CNAME 链与本地缓存，避免在错误层次修改应用代码。','f78ab6141242f5b7f3bc16b6e1034fa9a619fc73a6475c593460ffca19dc36fe',225,'{\"ip\": 2, \"cdn\": 2, \"dns\": 4, \"ttl\": 2, \"章\": 1, \"第\": 1, \"cname\": 1, \"一致\": 1, \"不开\": 1, \"与回\": 1, \"与安\": 1, \"与本\": 1, \"从根\": 1, \"代码\": 1, \"以实\": 1, \"会话\": 1, \"但健\": 1, \"低延\": 1, \"使用\": 1, \"保持\": 1, \"修改\": 1, \"健康\": 1, \"免在\": 1, \"决定\": 1, \"分发\": 1, \"分层\": 1, \"分布\": 1, \"切换\": 1, \"到权\": 1, \"制一\": 1, \"力有\": 1, \"务器\": 1, \"协议\": 1, \"单负\": 1, \"可访\": 1, \"名解\": 1, \"和会\": 1, \"响故\": 1, \"器从\": 1, \"器逐\": 1, \"回源\": 1, \"在错\": 1, \"地址\": 1, \"地缓\": 1, \"域到\": 1, \"域名\": 1, \"威服\": 1, \"存时\": 1, \"存结\": 1, \"存键\": 1, \"存静\": 1, \"安全\": 1, \"定缓\": 1, \"实现\": 1, \"就近\": 1, \"层分\": 1, \"层次\": 1, \"布式\": 1, \"常表\": 1, \"并缓\": 1, \"并通\": 1, \"应用\": 2, \"康检\": 1, \"延迟\": 1, \"开但\": 1, \"式系\": 1, \"归解\": 1, \"形成\": 1, \"影响\": 1, \"态资\": 1, \"成分\": 1, \"打不\": 1, \"把域\": 1, \"持能\": 1, \"换速\": 1, \"排查\": 1, \"控制\": 1, \"改应\": 1, \"故障\": 2, \"时要\": 1, \"时间\": 1, \"有限\": 1, \"服务\": 1, \"本地\": 1, \"权威\": 1, \"析为\": 1, \"析器\": 1, \"析结\": 1, \"查和\": 1, \"查时\": 1, \"查解\": 1, \"查询\": 1, \"根域\": 1, \"检查\": 2, \"次修\": 1, \"源策\": 1, \"点缓\": 1, \"现为\": 1, \"现简\": 1, \"用代\": 1, \"用协\": 1, \"用就\": 1, \"略控\": 1, \"站打\": 1, \"策略\": 1, \"简单\": 1, \"系统\": 1, \"级域\": 1, \"级查\": 1, \"结果\": 2, \"缓存\": 5, \"缘节\": 1, \"网站\": 1, \"能力\": 1, \"致性\": 1, \"节点\": 1, \"表现\": 1, \"要检\": 1, \"解析\": 3, \"议与\": 1, \"访问\": 2, \"话保\": 1, \"询可\": 1, \"误层\": 1, \"负载\": 1, \"资源\": 1, \"轮询\": 1, \"载分\": 1, \"边缘\": 1, \"过缓\": 1, \"过边\": 1, \"近访\": 1, \"逐级\": 1, \"递归\": 1, \"速度\": 1, \"避免\": 1, 