INSERT INTO `graph_nodes` (`id`, `uid`, `name`, `description`, `difficulty`, `related_course_label`, `sort_order`, `category_key`, `related_course_id`, `knowledge_point_id`) VALUES (24,'linear-algebra','线性代数','研究向量空间、线性变换与矩阵分解，是机器学习特征表示与深度学习的数学语言。','基础','数学基础',1,'foundation',NULL,NULL),(25,'probability','概率论与统计','描述不确定性、随机变量与统计推断，为模型评估和贝叶斯方法提供理论支撑。','基础','数学基础',2,'foundation',NULL,NULL),(26,'calculus','微积分','研究变化率与累积量，是理解梯度、优化和反向传播的必备基础。','基础','数学基础',3,'foundation',NULL,NULL),(27,'python','Python 程序设计','掌握 Python 语法、面向对象与科学计算生态，用于实现数据处理和模型实验。','基础','程序设计基础',4,'foundation',NULL,NULL),(28,'data-structures','数据结构','研究数据的组织、存储与访问方式，是算法设计与工程实现的共同基础。','基础','数据结构与算法',5,'core',13,NULL),(29,'algorithms','算法设计与分析','学习分治、动态规划、图算法及复杂度分析，建立系统化的算法思维。','进阶','数据结构与算法',6,'core',13,NULL),(30,'optimization','最优化方法','研究目标函数在约束下的极值求解，包括凸优化、梯度方法与对偶理论。','进阶','数学基础',7,'core',NULL,NULL),(31,'information-retrieval','信息检索','研究文档表示、倒排索引、相关性排序与评估指标，是 RAG 召回阶段的理论来源。','进阶','信息检索',8,'core',NULL,NULL),(32,'machine-learning','机器学习','从数据中归纳规律，覆盖线性模型、树模型、集成学习与模型评估。','进阶','机器学习',9,'core',9,51),(33,'deep-learning','深度学习','以多层神经网络学习层次化表示，覆盖优化、正则化与主流网络结构。','进阶','深度学习',10,'advanced',10,59),(34,'nlp','自然语言处理','研究文本表示、句法语义分析与语言生成，连接语言学与深度学习。','进阶','自然语言处理',11,'advanced',11,68),(35,'cv','计算机视觉','让机器理解图像与视频，涵盖卷积网络、目标检测与多模态感知。','进阶','计算机视觉',12,'advanced',12,71),(36,'rl','强化学习','通过与环境交互最大化长期回报，覆盖 MDP、价值学习与策略优化。','高阶','机器学习',13,'advanced',9,NULL),(37,'sequence-model','序列建模','处理变长序列中的时序依赖，包括 RNN、LSTM 与序列到序列结构。','进阶','深度学习',14,'advanced',10,62),(38,'knowledge-graph','知识图谱','以图结构组织实体与关系，支持知识推理、语义检索与可解释问答。','高阶','自然语言处理',15,'advanced',11,70),(39,'mlops','机器学习工程化','覆盖数据管道、实验追踪、模型部署与在线监控，将模型转化为可用服务。','进阶','机器学习',16,'advanced',9,54),(40,'transformer','Transformer','基于自注意力的并行序列建模架构，是现代大语言模型的结构基石。','高阶','深度学习',17,'llm',10,63),(41,'pretrained','预训练语言模型','通过大规模语料预训练获得通用语言能力，再迁移到下游任务。','高阶','自然语言处理',18,'llm',11,64),(42,'llm','大语言模型','具备大规模参数与涌现能力的生成式语言模型，涉及 Scaling Law 与对齐。','高阶','自然语言处理',19,'llm',11,NULL),(43,'finetuning','大模型微调','通过 SFT、LoRA 与偏好优化，使基础模型适配特定领域与任务要求。','高阶','深度学习',20,'llm',10,64),(44,'prompt-engineering','提示工程','设计结构化指令、上下文与输出约束，稳定激发大模型的目标能力。','进阶','自然语言处理',21,'llm',11,NULL),(45,'vector-db','向量数据库','面向高维向量的近似最近邻检索系统，支撑 RAG 的语义召回与更新。','进阶','数据库系统',22,'llm',15,94),(46,'rag','RAG 检索增强','将外部知识检索与生成模型结合，提升答案的事实性、时效性与可追溯性。','高阶','自然语言处理',23,'llm',11,69);
