INSERT INTO `knowledge_points` (`id`, `uid`, `name`, `chapter`, `chapter_no`, `difficulty`, `description`, `tags`, `sort_order`, `created_at`, `updated_at`, `course_id`) VALUES (51,'KP-ML-001','监督学习与假设空间','第 1 章 学习范式与优化',1,'入门','监督学习从带标签的数据中学习输入到输出的映射。设输入空间为 X、输出空间为 Y，学习器的任务是在假设空间 H 中寻找一个函数 f，使它对未见样本也有良好的预测能力。分类与回归是最常见的两类监督学习任务。 学习机器学习之前需要具备三块基础：线性代数帮助我们理解特征空间、矩阵分解与模型参数；概率统计提供条件概率、贝叶斯公式和分布建模的语言；微积分提供梯度与链式法则，是反向传播的数学前提。Python 和 NumPy 则负责把公式落实成可运行实验。','[\"ML\", \"机器学习\", \"监督学习\", \"反向传播\", \"监督学习与假设空间\"]',1,'2026-11-07 10:56:10.362700','2026-11-07 10:56:10.362712',9),(52,'KP-ML-002','损失函数与经验风险','第 1 章 学习范式与优化',1,'入门','损失函数衡量预测值与真实目标之间的差异。回归任务常用平方损失，分类任务常用交叉熵损失；交叉熵与 softmax 的组合能把模型输出转化为类别概率。训练过程通过最小化训练集上的平均损失来近似最小化真实风险。 经验风险最小化只优化有限训练样本，因此需要警惕过拟合。可以使用独立验证集选择超参数，使用测试集完成最终评估。类别不平衡时，需要同时查看精确率、召回率、F1 与 AUC，而不能只看准确率。','[\"ML\", \"机器学习\", \"损失函数\", \"过拟合\", \"损失函数与经验风险\"]',2,'2026-11-07 10:56:10.365869','2026-11-07 10:56:10.365883',9),(53,'KP-ML-003','梯度下降与学习率','第 1 章 学习范式与优化',1,'入门','梯度下降沿损失函数负梯度方向更新参数。学习率过大时更新会震荡甚至发散，过小时收敛缓慢。随机梯度下降每次只使用一个小批量样本估计梯度，可以降低计算成本，并通过梯度噪声帮助模型跳出部分局部极小值。 动量法累积历史梯度方向，减少震荡；RMSProp 根据梯度平方的移动平均缩放每个参数的学习率；Adam 结合一阶与二阶矩估计，是深度学习中常见的默认优化器。优化器不能替代数据质量，训练曲线异常时首先要检查特征、标签与学习率。','[\"ML\", \"机器学习\", \"损失函数\", \"梯度下降\", \"过拟合\", \"梯度下降与学习率\"]',3,'2026-11-07 10:56:10.368078','2026-11-07 10:56:10.368094',9),(54,'KP-ML-004','模型评估与交叉验证','第 2 章 泛化与模型选择',2,'进阶','模型评估的目标是估计模型在未知数据上的表现。固定划分训练集、验证集和测试集可以避免信息泄漏；测试集只能在模型与超参数确定后使用。小数据集可以使用 K 折交叉验证，让每个样本都有机会进入验证集。 分类任务可构建混淆矩阵，并计算精确率、召回率、F1 与 ROC-AUC。回归任务常使用均方误差、平均绝对误差和决定系数。评估指标必须与业务目标匹配，例如课程问答更关注答案忠实度与引用覆盖率，而非单纯的准确率。','[\"ML\", \"机器学习\", \"交叉验证\", \"模型评估与交叉验证\"]',4,'2026-11-07 10:56:10.372055','2026-11-07 10:56:10.372068',9),(55,'KP-ML-005','正则化与过拟合','第 2 章 泛化与模型选择',2,'进阶','过拟合表现为训练误差很低而验证误差较高。正则化通过约束模型复杂度降低方差。L2 正则让参数趋向较小的值，L1 正则可以产生稀疏权重；Dropout 在训练时随机屏蔽神经元，迫使网络学习冗余表示。 早停根据验证集表现停止训练，是一种简单有效的正则化。数据增强、集成学习和降低模型容量也可以缓解过拟合。模型越复杂，需要的训练数据通常越多；在样本有限时，简单模型往往比深层模型更可靠。','[\"ML\", \"机器学习\", \"过拟合\", \"集成学习\", \"复杂度\", \"正则化与过拟合\"]',5,'2026-11-07 10:56:10.375067','2026-11-07 10:56:10.375077',9),(56,'KP-ML-006','集成学习与偏差方差','第 2 章 泛化与模型选择',2,'进阶','集成学习把多个基学习器的结果组合起来，降低单模型的不稳定性。Bagging 对训练样本重采样并并行训练，主要降低方差；随机森林在此基础上增加特征随机性。Boosting 依次训练弱分类器，使新模型关注前面模型的错误，通常降低偏差。 偏差描述模型系统性偏离真实规律的程度，方差描述模型对训练集扰动的敏感程度。模型选择就是在两者之间寻找平衡。交叉验证与学习曲线能帮助我们判断偏差或方差哪一个更主要。','[\"ML\", \"机器学习\", \"交叉验证\", \"集成学习\", \"集成学习与偏差方差\"]',6,'2026-11-07 10:56:10.376441','2026-11-07 10:56:10.376451',9),(57,'KP-ML-007','机器学习的先修知识与依赖顺序','第 3 章 先修关系与学习路线',3,'进阶','机器学习的前置知识可以按依赖关系组织。第一步是 Python 与 NumPy，掌握数组、矩阵运算、广播和向量化；第二步是线性代数，理解矩阵乘法、特征值、奇异值分解及其在特征空间中的作用。 第三步是概率统计，重点是随机变量、条件概率、贝叶斯公式与常见分布；第四步是微积分与最优化，重点是偏导、链式法则、梯度下降和学习率。最后补充算法与数据结构基础，以便理解复杂度、索引与大规模数据处理。','[\"ML\", \"机器学习\", \"损失函数\", \"梯度下降\", \"复杂度\", \"索引\", \"机器学习的先修知识与依赖顺序\"]',7,'2026-11-07 10:56:10.377922','2026-11-07 10:56:10.377933',9),(58,'KP-ML-008','AI 工程师学习路线与阶段目标','第 3 章 先修关系与学习路线',3,'进阶','从零到 AI 工程师可以划分为四个阶段。阶段一用 4 到 6 周完成 Python、NumPy、线性代数与概率统计；阶段二是 6 到 8 周的机器学习，包括监督学习、损失函数、梯度下降、模型评估与集成学习。 阶段三进入深度学习与自然语言处理，学习反向传播、卷积与序列建模、Transformer 自注意力以及预训练语言模型；阶段四用 4 到 6 周完成 RAG 应用工程，包括文档切分、向量检索、重排序、提示模板、引用溯源和评测。','[\"ML\", \"机器学习\", \"监督学习\", \"损失函数\", \"梯度下降\", \"集成学习\", \"AI 工程师学习路线与阶段目标\"]',8,'2026-11-07 10:56:10.379397','2026-11-07 10:56:10.379409',9),(59,'KP-DL-001','反向传播与计算图','第 1 章 神经网络基础',1,'入门','神经网络由多层线性变换与非线性激活组成。前向传播把输入逐层映射为预测结果，损失函数衡量预测误差；反向传播利用链式法则，从输出层向输入层逐层计算损失对各参数的偏导。 计算图把运算组织成有向无环图，每个节点保存前向值，并在反向阶段接收上游梯度。Autograd 自动完成这一过程，使研究者可以专注模型结构。梯度消失和梯度爆炸是深层网络常见问题，原因包括激活饱和、权重初始化不当与连乘效应。','[\"DL\", \"深度学习\", \"损失函数\", \"过拟合\", \"反向传播\", \"神经网络\", \"反向传播与计算图\"]',1,'2026-11-07 10:56:10.406984','2026-11-07 10:56:10.407002',10),(60,'KP-DL-002','激活函数与优化器','第 1 章 神经网络基础',1,'入门','激活函数为网络引入非线性。Sigmoid 与 Tanh 在两端容易饱和；ReLU 计算简单，但可能出现神经元失活。GELU 和 SiLU 在 Transformer 与卷积网络中被广泛使用，能够提供更平滑的梯度。 优化器决定参数如何根据梯度更新。SGD 加动量在计算机视觉中表现稳定，AdamW 通过解耦权重衰减改善正则化效果。学习率调度包括余弦退火、线性预热和分段衰减，大模型训练通常需要预热阶段来避免早期不稳定。','[\"DL\", \"深度学习\", \"卷积\", \"Transformer\", \"激活函数与优化器\"]',2,'2026-11-07 10:56:10.411943','2026-11-07 10:56:10.411962',10),(61,'KP-DL-003','卷积神经网络','第 1 章 神经网络基础',1,'入门','卷积层通过局部连接和权重共享提取空间特征，显著减少参数量。多个卷积核可以学习边缘、纹理和更高层的语义模式；池化层降低空间分辨率，扩大后续层的有效感受野。 感受野描述一个神经元能够观察到的输入区域。堆叠小卷积核可以在保持较少参数量的同时增加感受野。残差连接让梯度能够跨层传播，使训练极深的网络成为可能。','[\"DL\", \"深度学习\", \"卷积\", \"图像\", \"目标检测\", \"卷积神经网络\"]',3,'2026-11-07 10:56:10.415050','2026-11-07 10:56:10.415079',10),(62,'KP-DL-004','循环网络与序列建模','第 2 章 序列、注意力与预训练',2,'进阶','循环神经网络在时间步之间共享参数，适合处理文本、语音和时间序列。隐藏状态把历史信息传递到当前时刻，但普通 RNN 难以学习长距离依赖，并存在梯度消失问题。 LSTM 通过输入门、遗忘门和输出门控制信息流动，GRU 使用更少的门控结构。双向循环网络可以同时利用过去和未来上下文，但不适合严格的在线生成场景。','[\"DL\", \"深度学习\", \"神经网络\", \"Transformer\", \"循环网络与序列建模\"]',4,'2026-11-07 10:56:10.421731','2026-11-07 10:56:10.421749',10),(63,'KP-DL-005','Transformer 与自注意力','第 2 章 序列、注意力与预训练',2,'进阶','自注意力通过 Query、Key、Value 计算序列中任意两个位置的相关性。缩放点积注意力先计算 Q 与 K 的点积，再除以维度的平方根，经过 softmax 得到权重，最后对 V 加权求和。 多头注意力在多个子空间并行建模不同类型的关系，再拼接输出。位置编码为模型注入顺序信息；残差连接和层归一化保证深层训练稳定。相比循环网络，Transformer 支持并行计算，具有更强的长距离依赖建模能力。','[\"DL\", \"深度学习\", \"Transformer\", \"自注意力\", \"Transformer 与自注意力\"]',5,'2026-11-07 10:56:10.426757','2026-11-07 10:56:10.426776',10),(64,'KP-DL-006','预训练与迁移学习','第 2 章 序列、注意力与预训练',2,'进阶','预训练语言模型先在大规模无标注语料上学习通用语言表示，再通过微调或提示适配下游任务。掩码语言建模、因果语言建模和序列到序列目标塑造了不同的模型能力。 微调可以用少量标注数据把通用模型迁移到特定领域；参数高效微调如 LoRA 只训练低秩增量矩阵，显著降低显存与存储成本。适配任务时要关注数据质量、灾难性遗忘和评估集泄漏。','[\"DL\", \"深度学习\", \"预训练\", \"检索增强\", \"预训练与迁移学习\"]',6,'2026-11-07 10:56:10.430898','2026-11-07 10:56:10.430913',10),(65,'KP-NLP-001','文本预处理与分词','第 4 章 文本表示与语义',1,'入门','自然语言处理首先要把连续文本转换为模型可处理的单元。中文没有天然空格边界，分词结果会直接影响后续检索与语义分析。常见方法包括基于词典的最大匹配、统计序列标注和基于预训练模型的分词器。 预处理还包括统一全半角、清理控制字符、规范化数字与英文大小写。是否去除停用词取决于任务：关键词检索需要保留重要术语，语义向量模型则可能从完整句中获得更好上下文。','[\"NLP\", \"自然语言处理\", \"预训练\", \"分词\", \"RAG\", \"重排序\", \"文本预处理与分词\"]',1,'2026-11-07 10:56:10.450407','2026-11-07 10:56:10.450420',11),(66,'KP-NLP-002','词袋模型与 TF-IDF','第 4 章 文本表示与语义',1,'入门','词袋模型把文本表示为词频向量，忽略词序但保留词汇出现模式。TF-IDF 在词频基础上乘以逆文档频率，降低高频常见词的权重，提高专有术语的区分度。 BM25 在 TF-IDF 基础上引入文档长度归一化和词频饱和机制，是信息检索中的经典排序函数。它计算开销低、可解释性强，适合与向量召回组成混合检索。','[\"NLP\", \"自然语言处理\", \"TF-IDF\", \"BM25\", \"RAG\", \"词袋模型与 TF-IDF\"]',2,'2026-11-07 10:56:10.455152','2026-11-07 10:56:10.455168',11),(67,'KP-NLP-003','词向量与上下文表示','第 4 章 文本表示与语义',1,'入门','词向量把词映射到低维连续空间，使语义相近的词具有相近的向量表示。Word2Vec 通过上下文预测学习静态词向量，但同一个词在不同语境下仍共享同一向量。 ELMo、BERT 等上下文语言模型根据整句动态生成词表示，能够区分多义词。句子向量则用于语义检索、聚类与相似度比较，常见做法包括池化编码器输出或使用专用 sentence embedding 模型。','[\"NLP\", \"自然语言处理\", \"词向量\", \"词向量与上下文表示\"]',3,'2026-11-07 10:56:10.456924','2026-11-07 10:56:10.456939',11),(68,'KP-NLP-004','预训练语言模型','第 12 章 大模型与 RAG',2,'进阶','预训练语言模型通过海量文本学习语法、事实与推理模式。BERT 类模型使用双向上下文和掩码预测，GPT 类模型使用自回归目标逐词生成。模型规模增大后会出现涌现能力，但也会增加训练、推理与部署成本。 大语言模型能够根据指令完成摘要、问答和代码生成，但可能产生幻觉。知识截止时间、训练数据偏差和缺乏引用也是实际应用中必须解决的问题。提示工程可以在一定程度上约束输出格式。','[\"NLP\", \"自然语言处理\", \"预训练\", \"检索增强\", \"预训练语言模型\"]',4,'2026-11-07 10:56:10.459338','2026-11-07 10:56:10.459354',11),(69,'KP-NLP-005','RAG 检索增强生成','第 12 章 大模型与 RAG',2,'进阶','RAG 将外部知识检索与生成模型结合。完整链路包括文档解析、语义切分、向量化、召回、重排序、上下文组装、答案生成与引用展示。检索到的高质量证据可以显著减少模型幻觉。 切分策略需要兼顾语义完整与检索粒度。块过大时噪声增加，块过小时上下文不完整；按标题与段落切分，并保留课程、章节、知识点 ID，有利于引用与重排。混合检索可以同时利用关键词精确命中与向量语义相似度。','[\"NLP\", \"自然语言处理\", \"RAG\", \"重排序\", \"RAG 检索增强生成\"]',5,'2026-11-07 10:56:10.461492','2026-11-07 10:56:10.461507',11),(70,'KP-NLP-006','信息抽取与知识图谱','第 12 章 大模型与 RAG',2,'进阶','信息抽取从非结构化文本中识别实体、关系与事件。命名实体识别、关系分类与事件抽取共同把文本转化为结构化知识。知识图谱以实体和关系构成网络，可以支持多跳查询与依赖分析。 图嵌入把实体与关系映射到向量空间，支持链接预测和知识补全。课程知识图谱可以表达知识点之间的先修关系，但不应混入用户掌握度或推荐排序等主观信息。','[\"NLP\", \"自然语言处理\", \"检索增强\", \"知识图谱\", \"信息抽取与知识图谱\"]',6,'2026-11-07 10:56:10.463062','2026-11-07 10:56:10.463074',11),(71,'KP-CV-001','数字图像与颜色空间','第 1 章 图像表示与卷积',1,'入门','数字图像是像素值的二维或三维数组。灰度图每个像素记录亮度，彩色图通常包含红、绿、蓝三个通道。像素值范围、颜色空间和归一化方式会直接影响模型训练。 RGB 适合显示，HSV 更适合颜色分割；Lab 空间试图让颜色差异更接近人类感知。图像预处理还包括尺寸缩放、裁剪、中心化和标准化。数据增强必须保持标签语义不变。','[\"CV\", \"计算机视觉\", \"图像\", \"数字图像与颜色空间\"]',1,'2026-11-07 10:56:10.478973','2026-11-07 10:56:10.478986',12),(72,'KP-CV-002','卷积运算与特征提取','第 1 章 图像表示与卷积',1,'入门','卷积核在输入图像上滑动，通过局部加权求和得到特征图。权重共享让同一个模式可以在图像任意位置被检测，大幅减少参数。多层卷积逐渐从边缘、纹理过渡到物体部件和语义概念。 步幅决定输出分辨率，填充控制边界信息，空洞卷积可以在不显著增加参数的情况下扩大感受野。批归一化与残差连接提升训练稳定性。','[\"CV\", \"计算机视觉\", \"过拟合\", \"卷积\", \"迁移学习\", \"图像\", \"卷积运算与特征提取\"]',2,'2026-11-07 10:56:10.480508','2026-11-07 10:56:10.480519',12),(73,'KP-CV-003','感受野与网络结构','第 1 章 图像表示与卷积',1,'入门','感受野表示网络中一个神经元对应的原始输入区域。多个小卷积核串联可以在扩大感受野的同时降低参数数量。深层特征通常具有更大的感受野，适合表示整体物体语义。 池化层降低特征图尺寸并增强局部平移不变性，但过度下采样会损失空间细节。目标检测和分割任务需要多尺度特征融合，以兼顾语义信息与定位精度。','[\"CV\", \"计算机视觉\", \"卷积\", \"目标检测\", \"感受野与网络结构\"]',3,'2026-11-07 10:56:10.481905','2026-11-07 10:56:10.481916',12),(74,'KP-CV-004','图像分类','第 5 章 视觉任务与多模态',2,'进阶','图像分类为整张图片预测一个或多个类别。数据质量、类别平衡和标注一致性通常比模型结构更重要。训练集需要覆盖不同光照、角度和背景，避免模型学习到与标签无关的捷径。 交叉熵是常见分类损失；多标签任务中每个类别独立使用 sigmoid。评价指标包括 Top-1、Top-5、精确率、召回率和混淆矩阵。类别不平衡时可以使用重采样、类别权重或 focal loss。','[\"CV\", \"计算机视觉\", \"图像\", \"图像分类\"]',4,'2026-11-07 10:56:10.483295','2026-11-07 10:56:10.483306',12),(75,'KP-CV-005','目标检测','第 5 章 视觉任务与多模态',2,'进阶','目标检测需要同时预测物体类别与边界框。两阶段方法先生成候选区域再分类回归，单阶段方法直接在特征图上预测。锚框、中心点与查询式检测器代表不同设计思路。 IoU 衡量预测框与真实框的重合程度，NMS 用于去除重复检测。平均精度 mAP 综合考虑不同类别和 IoU 阈值，是目标检测的主流指标。','[\"CV\", \"计算机视觉\", \"目标检测\"]',5,'2026-11-07 10:56:10.484650','2026-11-07 10:56:10.484675',12),(76,'KP-CV-006','语义分割与多模态','第 5 章 视觉任务与多模态',2,'进阶','语义分割为每个像素分配类别，实例分割进一步区分同类不同实例。编码器—解码器结构通过跳跃连接融合浅层空间信息与深层语义信息，常用于医学影像与自动驾驶。 视觉—语言模型把图像编码与文本编码映射到共享空间，支持图文检索、图像描述和视觉问答。构建多模态 RAG 时，应保留图像来源、区域与文本说明，以便生成可追溯的证据。','[\"CV\", \"计算机视觉\", \"RAG\", \"图像\", \"语义分割\", \"多模态\", \"语义分割与多模态\"]',6,'2026-11-07 10:56:10.487714','2026-11-07 10:56:10.487731',12),(77,'KP-DSA-001','时间复杂度与空间复杂度','第 1 章 复杂度与线性结构',1,'入门','复杂度分析用输入规模的增长趋势评估算法成本。大 O 记号忽略常数与低阶项，描述算法在最坏情况下的渐近上界。常见复杂度包括 O(1)、O(log n)、O(n)、O(n log n) 和 O(n²)。 空间复杂度统计算法额外使用的内存。递归调用栈、哈希表和辅助数组都可能成为空间瓶颈。实际工程中还要考虑缓存局部性、常数因子和输入分布。','[\"DSA\", \"数据结构与算法\", \"复杂度\", \"哈希\", \"时间复杂度与空间复杂度\"]',1,'2026-11-07 10:56:10.507508','2026-11-07 10:56:10.507521',13),(78,'KP-DSA-002','数组、链表、栈与队列','第 1 章 复杂度与线性结构',1,'入门','数组支持 O(1) 随机访问，但中间插入可能触发搬移；动态数组扩容需要均摊分析。链表插入删除灵活，却失去连续内存的缓存优势。 栈遵循后进先出，适合表达式求值、括号匹配和深度优先搜索；队列遵循先进先出，适合广度优先搜索和任务调度。双端队列可在两端高效插入删除。','[\"DSA\", \"数据结构与算法\", \"复杂度\", \"数组、链表、栈与队列\"]',2,'2026-11-07 10:56:10.509662','2026-11-07 10:56:10.509677',13),(79,'KP-DSA-003','哈希表与集合','第 1 章 复杂度与线性结构',1,'入门','哈希表通过哈希函数把键映射到桶，实现平均 O(1) 的查找、插入与删除。冲突处理包括链地址法和开放寻址；负载因子过高会显著增加冲突。 哈希表的最坏复杂度可能退化到 O(n)，因此需要关注哈希质量与扩容策略。Python dict、Java HashMap 等实现细节不同，迭代顺序和内存占用也不同。','[\"DSA\", \"数据结构与算法\", \"复杂度\", \"哈希\", \"索引\", \"哈希表与集合\"]',3,'2026-11-07 10:56:10.511217','2026-11-07 10:56:10.511230',13),(80,'KP-DSA-004','二叉树与堆','第 2 章 树、图与算法设计',2,'进阶','二叉树每个节点最多有两个子节点。二叉搜索树在平衡时支持 O(log n) 查找，但可能退化为链。AVL 树与红黑树通过旋转维持平衡，是许多标准库有序映射的基础。 堆是一棵完全二叉树，满足父节点优先级高于或低于子节点。二叉堆支持 O(1) 查看堆顶和 O(log n) 插入删除，可用于优先队列、Top-K 和 Dijkstra 算法。','[\"DSA\", \"数据结构与算法\", \"二叉树\", \"二叉树与堆\"]',4,'2026-11-07 10:56:10.512628','2026-11-07 10:56:10.512640',13),(81,'KP-DSA-005','图的遍历与最短路径','第 2 章 树、图与算法设计',2,'进阶','图由顶点和边构成，可用邻接表或邻接矩阵表示。邻接表适合稀疏图，邻接矩阵适合快速判断两点是否相连。DFS 适合连通性、环检测和拓扑排序，BFS 可求无权图最短路径。 Dijkstra 适用于非负权图，基于优先队列实现；Bellman-Ford 可处理负权边并检测负环；Floyd-Warshall 求所有点对最短路径。拓扑排序要求图是有向无环图。','[\"DSA\", \"数据结构与算法\", \"知识图谱\", \"图的遍历与最短路径\"]',5,'2026-11-07 10:56:10.513979','2026-11-07 10:56:10.513989',13),(82,'KP-DSA-006','动态规划','第 2 章 树、图与算法设计',2,'进阶','动态规划把大问题拆成重叠子问题，通过保存状态避免重复计算。设计步骤包括定义状态、写出转移方程、确定初始条件和遍历顺序。状态设计决定了算法的正确性与复杂度。 背包、最长公共子序列和最短编辑距离是经典问题。滚动数组可以降低空间复杂度，但必须保证状态转移依赖的顺序。许多序列与区间问题也可以通过记忆化搜索实现。','[\"DSA\", \"数据结构与算法\", \"复杂度\", \"动态规划\"]',6,'2026-11-07 10:56:10.516692','2026-11-07 10:56:10.516702',13),(83,'KP-OS-001','进程、线程与上下文切换','第 2 章 进程与并发',1,'入门','进程是操作系统进行资源分配的基本单位，拥有独立地址空间；线程是调度的基本单位，同一进程内的线程共享代码、数据和打开的文件。线程切换成本通常低于进程切换。 上下文切换保存和恢复寄存器、程序计数器和栈信息。频繁切换会增加系统开销；大量短任务、锁竞争和阻塞 I/O 都可能引起切换风暴。','[\"OS\", \"操作系统\", \"进程\", \"线程\", \"进程、线程与上下文切换\"]',1,'2026-11-07 10:56:10.532812','2026-11-07 10:56:10.532825',14),(84,'KP-OS-002','CPU 调度','第 2 章 进程与并发',1,'入门','调度器决定哪个就绪进程或线程获得 CPU。先来先服务简单但容易产生长任务阻塞；最短作业优先能降低平均等待时间，却需要预知运行时间。时间片轮转适合交互系统。 优先级调度需要处理饥饿问题，可以使用老化机制逐渐提高长期等待任务的优先级。多级反馈队列结合时间片和优先级，根据任务行为动态调整调度策略。','[\"OS\", \"操作系统\", \"进程\", \"线程\", \"CPU 调度\"]',2,'2026-11-07 10:56:10.534334','2026-11-07 10:56:10.534345',14),(85,'KP-OS-003','同步、互斥与死锁','第 2 章 进程与并发',1,'入门','并发访问共享数据会产生竞态条件。互斥锁保证同一时刻只有一个线程进入临界区，信号量用于控制有限资源的访问，条件变量用于等待某个状态成立。 锁会带来开销、优先级反转和死锁风险。死锁的四个必要条件是互斥、占有并等待、不可抢占和循环等待。破坏任一条件即可预防死锁，也可以通过资源有序分配避免循环等待。','[\"OS\", \"操作系统\", \"线程\", \"死锁\", \"同步、互斥与死锁\"]',3,'2026-11-07 10:56:10.536662','2026-11-07 10:56:10.536678',14),(86,'KP-OS-004','虚拟内存','第 4 章 内存与文件系统',2,'进阶','虚拟内存为每个进程提供独立地址空间，通过页表把虚拟地址映射到物理页。它提高了隔离性与内存利用率，并允许程序使用比物理内存更大的地址空间。 按需分页只在访问页面时加载数据；缺页中断会把页面从磁盘换入内存。页表项包含有效位、访问位和修改位，供置换算法决策。TLB 缓存最近使用的地址转换结果。','[\"OS\", \"操作系统\", \"进程\", \"虚拟内存\"]',4,'2026-11-07 10:56:10.538690','2026-11-07 10:56:10.538705',14),(87,'KP-OS-005','页面置换算法','第 4 章 内存与文件系统',2,'进阶','当物理页不足时，需要选择页面换出。FIFO 简单但可能出现 Belady 异常；LRU 依据最近访问时间淘汰最久未使用页面，效果较好但维护成本高。 CLOCK 算法用访问位近似 LRU，在实际操作系统中广泛使用。工作集模型根据近期访问判断进程当前需要的页面集合，防止抖动。','[\"OS\", \"操作系统\", \"进程\", \"页面置换算法\"]',5,'2026-11-07 10:56:10.541092','2026-11-07 10:56:10.541112',14),(88,'KP-OS-006','文件系统','第 4 章 内存与文件系统',2,'进阶','文件系统把持久存储抽象为文件和目录，负责命名、权限、空间分配与数据检索。inode 记录文件元数据和数据块指针，目录把文件名映射到 inode。 日志文件系统在写入前记录事务日志，提高崩溃恢复能力；写时复制文件系统通过复制修改块保持一致性。缓存可以显著提高读写性能，但需要处理写回与断电一致性。','[\"OS\", \"操作系统\", \"文件系统\", \"事务\"]',6,'2026-11-07 10:56:10.544073','2026-11-07 10:56:10.544089',14),(89,'KP-DB-001','关系模型与范式','第 1 章 关系模型与查询',1,'入门','关系数据库用二维表表示实体与联系。关系模式定义属性与约束，主键唯一标识一行，外键保证跨表引用完整性。SQL 通过 SELECT、INSERT、UPDATE、DELETE 操作数据。 范式化通过拆分表减少冗余与更新异常。第一范式要求属性原子，第二范式消除非主属性对候选键的部分依赖，第三范式消除传递依赖。过度范式化会增加连接开销，实际设计需要在一致性与查询性能之间权衡。','[\"DB\", \"数据库系统\", \"索引\", \"关系模型与范式\"]',1,'2026-11-07 10:56:10.560480','2026-11-07 10:56:10.560493',15),(90,'KP-DB-002','SQL 查询与聚合','第 1 章 关系模型与查询',1,'入门','SQL 查询通常由 FROM、WHERE、GROUP BY、HAVING、SELECT、ORDER BY 和 LIMIT 组成。聚合函数对分组数据计算统计值，窗口函数可以在不折叠行的前提下完成排名、累计与移动平均。 连接用于组合多张表，内连接只保留匹配行，左连接保留左表全部行。子查询可以出现在 WHERE、FROM 或 SELECT 中；相关子查询会引用外层查询的字段。','[\"DB\", \"数据库系统\", \"SQL 查询与聚合\"]',2,'2026-11-07 10:56:10.563397','2026-11-07 10:56:10.563408',15),(91,'KP-DB-003','索引与 B+ 树','第 1 章 关系模型与查询',1,'入门','索引通过额外的数据结构加速查询。B+ 树将有序键组织为多路平衡树，叶子节点通过链表连接，适合范围查询和排序。联合索引遵循最左前缀原则。 索引会占用空间并增加写入成本。低选择性的列通常不适合单独建索引；频繁用于过滤、连接和排序的列更值得索引。覆盖索引可以让查询直接从索引返回结果，减少回表。','[\"DB\", \"数据库系统\", \"索引\", \"索引与 B+ 树\"]',3,'2026-11-07 10:56:10.564770','2026-11-07 10:56:10.564781',15),(92,'KP-DB-004','事务与 ACID','第 6 章 事务与向量检索',2,'进阶','事务是一组要么全部成功、要么全部失败的数据库操作。原子性保证部分失败会回滚，一致性保证约束不被破坏，隔离性控制并发事务之间的可见性，持久性保证提交后的数据不会丢失。 数据库通过 undo 日志、redo 日志和锁机制实现事务。长事务会持有资源并阻碍清理，应尽量缩短事务范围。应用层重试要幂等，避免重复提交。','[\"DB\", \"数据库系统\", \"事务\", \"事务与 ACID\"]',4,'2026-11-07 10:56:10.567302','2026-11-07 10:56:10.567312',15),(93,'KP-DB-005','隔离级别与并发控制','第 6 章 事务与向量检索',2,'进阶','SQL 标准定义读未提交、读已提交、可重复读和串行化四种隔离级别。不同级别对应脏读、不可重复读和幻读的可见性权衡。MySQL InnoDB 默认使用可重复读，并通过 MVCC 提供一致性快照。 MVCC 让读写互不阻塞，但需要清理旧版本。间隙锁与临键锁用于处理范围条件，可能增加死锁概率。应用应尽量按固定顺序访问资源，并设置合理的锁等待超时。','[\"DB\", \"数据库系统\", \"死锁\", \"事务\", \"隔离级别\", \"隔离级别与并发控制\"]',5,'2026-11-07 10:56:10.569316','2026-11-07 10:56:10.569330',15),(94,'KP-DB-006','向量数据库与相似检索','第 6 章 事务与向量检索',2,'进阶','向量数据库面向高维向量的近似最近邻检索。常见索引包括 HNSW、IVF 与 PQ。HNSW 通过分层图结构平衡召回率与查询速度，适合低延迟在线检索；IVF 通过聚类缩小搜索范围。 MySQL 8 没有原生向量类型，可以把 embedding 存为 JSON 并在线做精确余弦相似度计算。数据量较小时这种方式简单可靠；数据增大后应迁移到专用向量数据库或支持 pgvector 的 PostgreSQL。','[\"DB\", \"数据库系统\", \"BM25\", \"重排序\", \"索引\", \"向量数据库\", \"向量数据库与相似检索\"]',6,'2026-11-07 10:56:10.570907','2026-11-07 10:56:10.570919',15),(95,'KP-NET-001','网络分层与 TCP/IP','第 1 章 分层模型与传输层',1,'入门','网络协议采用分层设计以降低复杂度。OSI 模型包含物理层、数据链路层、网络层、传输层、会话层、表示层和应用层；TCP/IP 模型把功能归纳为网络接口层、网际层、传输层和应用层。 分层提供了清晰的接口边界，使不同厂商和设备可以互操作。IP 负责主机之间的寻址与路由，TCP/UDP 负责进程之间的通信，HTTP、DNS 等应用协议建立在传输层之上。','[\"NET\", \"计算机网络\", \"复杂度\", \"进程\", \"TCP\", \"HTTP\", \"网络分层与 TCP/IP\"]',1,'2026-11-07 10:56:10.590312','2026-11-07 10:56:10.590331',16),(96,'KP-NET-002','TCP 可靠传输','第 1 章 分层模型与传输层',1,'入门','TCP 通过序列号、确认应答、超时重传和校验和提供可靠字节流。接收方使用累计确认告诉发送方已经收到哪些数据；乱序包会在缓冲区中等待完整后再交付应用。 滑动窗口允许发送方在未收到确认时连续发送多个段，提高吞吐量。流量控制通过接收窗口防止接收方被淹没；拥塞控制则根据网络状况调整发送速率。','[\"NET\", \"计算机网络\", \"TCP\", \"拥塞控制\", \"TCP 可靠传输\"]',2,'2026-11-07 10:56:10.592970','2026-11-07 10:56:10.593000',16),(97,'KP-NET-003','TCP 拥塞控制','第 1 章 分层模型与传输层',1,'入门','拥塞控制根据网络反馈调整发送窗口，避免过多数据导致网络崩溃。慢启动阶段窗口指数增长，达到阈值后进入拥塞避免，线性增长；丢包时根据算法减小窗口。 经典算法包括 Reno、CUBIC 和 BBR。CUBIC 根据时间函数增长窗口，适合高带宽长距离网络；BBR 通过测量带宽和往返时延主动估计网络瓶颈，不完全依赖丢包信号。','[\"NET\", \"计算机网络\", \"拥塞控制\", \"TCP 拥塞控制\"]',3,'2026-11-07 10:56:10.596257','2026-11-07 10:56:10.596275',16),(98,'KP-NET-004','HTTP 与 HTTPS','第 5 章 应用协议与安全',2,'进阶','HTTP 是请求—响应式应用层协议。请求包含方法、路径、头部和可选正文；响应包含状态码、头部和正文。缓存控制、内容协商与连接复用是性能优化的重要部分。 HTTP/2 通过多路复用、头部压缩和服务器推送减少延迟；HTTP/3 基于 QUIC，使用 UDP 实现连接建立与拥塞控制。不同版本的实际收益取决于网络环境与客户端支持。','[\"NET\", \"计算机网络\", \"拥塞控制\", \"HTTP\", \"HTTPS\", \"HTTP 与 HTTPS\"]',4,'2026-11-07 10:56:10.598630','2026-11-07 10:56:10.598648',16),(99,'KP-NET-005','DNS 与 CDN','第 5 章 应用协议与安全',2,'进阶','DNS 把域名解析为 IP 地址，形成分层分布式系统。递归解析器从根域、顶级域到权威服务器逐级查询，并缓存结果。TTL 决定缓存时间，影响故障切换速度。 DNS 轮询可以实现简单负载分发，但健康检查和会话保持能力有限。CDN 通过边缘节点缓存静态资源，使用就近访问降低延迟，并通过缓存键与回源策略控制一致性。','[\"NET\", \"计算机网络\", \"DNS\", \"DNS 与 CDN\"]',5,'2026-11-07 10:56:10.600797','2026-11-07 10:56:10.600813',16),(100,'KP-NET-006','网络安全基础','第 5 章 应用协议与安全',2,'进阶','网络安全需要同时考虑机密性、完整性和可用性。常见风险包括注入、越权、跨站脚本、跨站请求伪造、重放攻击和敏感信息泄漏。 防护措施包括最小权限、输入校验、参数化查询、输出编码、HTTPS、短期令牌与速率限制。认证解决“你是谁”，授权解决“你能做什么”，两者不能混为一谈。','[\"NET\", \"计算机网络\", \"HTTP\", \"HTTPS\", \"网络安全\", \"网络安全基础\"]',6,'2026-11-07 10:56:10.603530','2026-11-07 10:56:10.603547',16);
